unsafe extern "C" fn impl_from_IDirectDrawClipper(iface: *mut IDirectDrawClipper) -> *mut ddraw_clipper {
    return (iface as *mut u8).wrapping_sub(core::mem::offset_of!(ddraw_clipper, IDirectDrawClipper_iface)) as *mut ddraw_clipper;
}
#[no_mangle]
pub unsafe extern "C" fn ddraw_clipper_is_valid(clipper: *const ddraw_clipper) -> BOOL {
    /* Native is very lenient when you invoke the clipper methods with a clipper pointer that
     * points to something that is either not accessible or not a clipper, or if you break
     * a clipper after assigning it to a surface. Deus Ex: Goty depends on this. */

    if IsBadReadPtr(clipper as *const core::ffi::c_void, core::mem::size_of::<ddraw_clipper>() as UINT_PTR) != 0
    {
        WARN!("The application gave us an invalid clipper pointer %p.\n", clipper);
        return (FALSE) as BOOL;
    }
    if (*clipper).IDirectDrawClipper_iface.lpVtbl != core::ptr::addr_of!(ddraw_clipper_vtbl) as *const _
    {
        WARN!("The clipper vtable is modified: %p, expected %p.\n",
                (*clipper).IDirectDrawClipper_iface.lpVtbl, core::ptr::addr_of!(ddraw_clipper_vtbl));
        return (FALSE) as BOOL;
    }

    return (TRUE) as BOOL;
}

unsafe extern "system" fn ddraw_clipper_QueryInterface(iface: *mut IDirectDrawClipper, iid: REFIID, object: *mut *mut core::ffi::c_void) -> HRESULT {
    let clipper: *mut ddraw_clipper = impl_from_IDirectDrawClipper(iface);

    if ddraw_clipper_is_valid(clipper) == 0 {
        return DDERR_INVALIDPARAMS;
    }

    if IsEqualGUID!(core::ptr::addr_of!(IID_IDirectDrawClipper) as *const GUID, iid)!= false
        || IsEqualGUID!(core::ptr::addr_of!(IID_IUnknown) as *const GUID, iid) != false
    {
        IDirectDrawClipper_AddRef(core::ptr::addr_of_mut!((*clipper).IDirectDrawClipper_iface));
        *object = core::ptr::addr_of_mut!((*clipper).IDirectDrawClipper_iface) as *mut core::ffi::c_void;
        return S_OK;
    }

    WARN!("%s not implemented, returning E_NOINTERFACE.\n", debugstr_guid(iid));
    *object = core::ptr::null_mut();

    return E_NOINTERFACE;
}

unsafe extern "system" fn ddraw_clipper_AddRef(iface: *mut IDirectDrawClipper) -> ULONG {
    let clipper: *mut ddraw_clipper = impl_from_IDirectDrawClipper(iface);
    let mut refcount: ULONG;

    if ddraw_clipper_is_valid(clipper) == 0 {
        WARN!("Invalid clipper, returning 0.\n");
        return 0;
    }

    refcount = InterlockedIncrement(core::ptr::addr_of_mut!((*clipper).ref_) as *mut i32) as ULONG;
    TRACE!("%p increasing refcount to %lu.\n", clipper, refcount);
    return refcount;
}

unsafe extern "system" fn ddraw_clipper_Release(iface: *mut IDirectDrawClipper) -> ULONG {
    let mut clipper: *mut ddraw_clipper = impl_from_IDirectDrawClipper(iface);
    let mut refcount: ULONG = 0;

    if ddraw_clipper_is_valid(clipper) == 0 {
        WARN!("Invalid clipper, returning 0.\n");
        return 0;
    }

    refcount = InterlockedDecrement(
        core::ptr::addr_of_mut!((*clipper).ref_) as *mut ::core::ffi::c_long,
    ) as ULONG;

    if refcount == 0 {
        if !(*clipper).region.is_null() {
            DeleteObject((*clipper).region as HGDIOBJ);
        }
        /* make sure the object is no longer considered valid */
        // sizeof(clipper->IDirectDrawClipper_iface.lpVtbl): the POINTER. The translation took
        // the pointee's size (the 9-slot vtable struct), zeroed 36/72 bytes past the 4/8 bytes
        // of the field, ran off the end of the clipper's heap block, and every last Release
        // crashed in free() (modrun ddraw.logic).
        SecureZeroMemory(
            core::ptr::addr_of_mut!((*clipper).IDirectDrawClipper_iface.lpVtbl) as PVOID,
            core::mem::size_of::<*const IDirectDrawClipperVtbl>() as SIZE_T,
        );
        free(clipper as *mut ::core::ffi::c_void);
    }

    return refcount;
}

unsafe extern "system" fn ddraw_clipper_SetHWnd(iface: *mut IDirectDrawClipper, flags: DWORD, window: HWND) -> HRESULT {
    let clipper: *mut ddraw_clipper = impl_from_IDirectDrawClipper(iface);

    if ddraw_clipper_is_valid(clipper) == 0 {
        return DDERR_INVALIDPARAMS;
    }

    if flags != 0 {
        return DDERR_INVALIDPARAMS;
    }

    wined3d_mutex_lock();
    (*clipper).window = window;
    wined3d_mutex_unlock();

    return DD_OK;
}

unsafe extern "C" fn get_window_region(window: HWND) -> HRGN {
    let mut origin: POINT = core::mem::zeroed();
    let mut rgn: HRGN = core::ptr::null_mut();
    let mut dc: HDC = core::ptr::null_mut();

    dc = GetDC(window);
    if dc.is_null() {
        WARN!("Failed to get dc.\n");
        return core::ptr::null_mut();
    }

    rgn = CreateRectRgn(0, 0, 0, 0);
    if rgn.is_null() {
        ERR!("Failed to create region.\n");
        ReleaseDC(window, dc);
        return core::ptr::null_mut();
    }

    if GetRandomRgn(dc, rgn, (SYSRGN) as INT) != 1 {
        ERR!("Failed to get window region.\n");
        DeleteObject((rgn).cast());
        ReleaseDC(window, dc);
        return core::ptr::null_mut();
    }

    if (GetVersion() & 0x80000000) != 0 {
        GetDCOrgEx(dc, &mut origin);
        OffsetRgn(rgn, origin.x, origin.y);
    }

    ReleaseDC(window, dc);
    rgn
}

unsafe extern "system" fn ddraw_clipper_GetClipList(
    iface: *mut IDirectDrawClipper,
    rect: *mut RECT,
    clip_list: *mut RGNDATA,
    clip_list_size: *mut DWORD,
) -> HRESULT {
    let clipper: *mut ddraw_clipper = impl_from_IDirectDrawClipper(iface);
    let mut region: HRGN = core::ptr::null_mut();

    TRACE!(
        "iface %p, rect %s, clip_list %p, clip_list_size %p.\n",
        iface,
        wine_dbgstr_rect(rect),
        clip_list,
        clip_list_size
    );

    if ddraw_clipper_is_valid(clipper) == 0 {
        return DDERR_INVALIDPARAMS;
    }

    wined3d_mutex_lock();

    if !(*clipper).window.is_null() {
        region = get_window_region((*clipper).window);
        if region.is_null() {
            wined3d_mutex_unlock();
            WARN!("Failed to get window region.\n");
            return E_FAIL;
        }
    } else {
        region = (*clipper).region;
        if region.is_null() {
            wined3d_mutex_unlock();
            WARN!("No clip list set.\n");
            return DDERR_NOCLIPLIST;
        }
    }

    if !rect.is_null() {
        let mut clip_region: HRGN = core::ptr::null_mut();

        clip_region = CreateRectRgnIndirect(rect as LPCRECT);
        if clip_region.is_null() {
            wined3d_mutex_unlock();
            ERR!("Failed to create region.\n");
            if !(*clipper).window.is_null() {
                DeleteObject(region as HGDIOBJ);
            }
            return E_FAIL;
        }

        if CombineRgn(clip_region, region, clip_region, (RGN_AND as i32)) == (ERROR as i32) {
            wined3d_mutex_unlock();
            ERR!("Failed to combine regions.\n");
            DeleteObject(clip_region as HGDIOBJ);
            if !(*clipper).window.is_null() {
                DeleteObject(region as HGDIOBJ);
            }
            return E_FAIL;
        }

        if !(*clipper).window.is_null() {
            DeleteObject(region as HGDIOBJ);
        }
        region = clip_region;
    }

    *clip_list_size = GetRegionData(region, *clip_list_size, clip_list as LPRGNDATA);
    if !rect.is_null() || !(*clipper).window.is_null() {
        DeleteObject(region as HGDIOBJ);
    }

    wined3d_mutex_unlock();
    return DD_OK;
}

unsafe extern "system" fn ddraw_clipper_SetClipList(iface: *mut IDirectDrawClipper, region: *mut RGNDATA, flags: DWORD) -> HRESULT {
    let mut clipper: *mut ddraw_clipper = impl_from_IDirectDrawClipper(iface);

    TRACE!("iface %p, region %p, flags %#lx.\n", iface, region, flags);

    if ddraw_clipper_is_valid(clipper) == 0 {
        return DDERR_INVALIDPARAMS;
    }

    wined3d_mutex_lock();

    if !(*clipper).window.is_null() {
        wined3d_mutex_unlock();
        return DDERR_CLIPPERISUSINGHWND;
    }

    if !(*clipper).region.is_null() {
        DeleteObject((*clipper).region as HGDIOBJ);
    }
    if region.is_null() {
        (*clipper).region = core::ptr::null_mut::<HRGN__>();
    } else {
        (*clipper).region = ExtCreateRegion(core::ptr::null::<XFORM>(), 0, region);
        if (*clipper).region.is_null() {
            wined3d_mutex_unlock();
            ERR!("Failed to create region.\n");
            return E_FAIL;
        }
    }

    wined3d_mutex_unlock();

    return DD_OK;
}

unsafe extern "system" fn ddraw_clipper_GetHWnd(iface: *mut IDirectDrawClipper, window: *mut HWND) -> HRESULT {
    let clipper: *mut ddraw_clipper = impl_from_IDirectDrawClipper(iface);

    if ddraw_clipper_is_valid(clipper) == 0 {
        return DDERR_INVALIDPARAMS;
    }

    wined3d_mutex_lock();
    *window = (*clipper).window;
    wined3d_mutex_unlock();

    return DD_OK;
}

unsafe extern "system" fn ddraw_clipper_Initialize(
    iface: *mut IDirectDrawClipper,
    ddraw: *mut IDirectDraw,
    flags: DWORD,
) -> HRESULT {
    let clipper: *mut ddraw_clipper = impl_from_IDirectDrawClipper(iface);

    if ddraw_clipper_is_valid(clipper) == 0 {
        return DDERR_INVALIDPARAMS;
    }

    wined3d_mutex_lock();
    if (*clipper).initialized != 0 {
        wined3d_mutex_unlock();
        return DDERR_ALREADYINITIALIZED;
    }

    (*clipper).initialized = (TRUE as i32);
    wined3d_mutex_unlock();

    return DD_OK;
}

unsafe extern "system" fn ddraw_clipper_IsClipListChanged(iface: *mut IDirectDrawClipper, changed: *mut BOOL) -> HRESULT {
    let mut clipper: *mut ddraw_clipper = impl_from_IDirectDrawClipper(iface);

    DPRINT1!("iface %p, changed %p stub!\n", iface, changed);

    if ddraw_clipper_is_valid(clipper) == 0 {
        return DDERR_INVALIDPARAMS;
    }

    /* XXX What is safest? */
    *changed = (FALSE as i32);

    return DD_OK;
}
#[no_mangle]
pub unsafe extern "C" fn ddraw_clipper_init(clipper: *mut ddraw_clipper) -> HRESULT {
    (*clipper).IDirectDrawClipper_iface.lpVtbl =
        &raw const ddraw_clipper_vtbl as *const IDirectDrawClipperVtbl;
    (*clipper).ref_ = 1 as LONG;

    return DD_OK;
}
#[no_mangle]
pub unsafe extern "C" fn unsafe_impl_from_IDirectDrawClipper(iface: *mut IDirectDrawClipper) -> *mut ddraw_clipper {
    if iface.is_null() {
        return core::ptr::null_mut();
    }
    assert!(((*iface).lpVtbl as *const () == core::ptr::addr_of!(ddraw_clipper_vtbl) as *const ()));

    return impl_from_IDirectDrawClipper(iface);
}

